13	bool AdminOrderService::submit(const std::string& admin_id,
14	                               const std::string& batch_id,
15	                               int count) {
16	    std::cout << "admin-order: submitting batch=" << batch_id << "\n";
17	    if (!inventory_.reserve(batch_id, count)) return false;
18	    if (!payment_.authorize(admin_id, count * 5.0)) return false;
19	    repo_.bulkSave(batch_id, count);
