11	bool OrderService::submit(const std::string& user_id,
12	                          const std::string& item_id,
13	                          int quantity) {
14	    std::cout << "order: submitting item=" << item_id << " for user=" << user_id << "\n";
15	    if (!inventory_.reserve(item_id, quantity)) return false;
16	    if (!payment_.authorize(user_id, 9.99 * quantity)) return false;
17	    repo_.save(user_id, item_id, quantity);
18	    return true;
19	}
20	
21	bool OrderService::cancel(const std::string& order_id) {
22	    std::cout << "order: cancelling order=" << order_id << "\n";
23	    return repo_.update(order_id, "cancelled");
24	}
